using Dapper;
using Npgsql;
using PosApi.Auth;
using PosApi.Common;
using PosApi.Data;

namespace PosApi.Features.Sales;

public sealed record SaleLineInput(
    string ItemId,
    decimal Quantity,
    long UnitPriceH,
    long LineDiscountH,
    string? Note);

public sealed record SalePaymentInput(string Method, long AmountH, string? Reference);

public sealed record CommitSaleRequest(
    /*
     * One key per attempt, generated by the client.
     *
     * A retry after a timeout sends the same key, and the server returns the
     * original sale instead of creating a second one. Without it, a dropped
     * response means the client cannot tell success from failure — and retrying
     * is the reasonable thing to do.
     */
    string? IdempotencyKey,
    string BranchId,
    string? CustomerId,
    string? ServedByUserId,
    string? DiscountId,
    long DiscountH,
    long? TenderedH,
    IReadOnlyList<SaleLineInput> Lines,
    IReadOnlyList<SalePaymentInput> Payments,
    /*
     * Who approved a discount above its approval threshold. The signed-in
     * user may name themself (they must hold discounts.approve); naming
     * anyone else needs that person's password in ApproverPassword. Ignored
     * when the discount needs no approval.
     */
    string? ApprovedByUserId = null,
    string? ApproverPassword = null,
    /* dine_in | takeaway | delivery | other — shown on the kitchen board. */
    string? OrderType = null,
    /*
     * Why a price or discount differs from the catalog and the discount rules.
     * The server prices the sale itself: a line price must equal the catalog
     * price and the invoice discount must be what DiscountId gives. Anything
     * else is an override, accepted only with this reason and someone holding
     * pos.override_price (the cashier, or ApprovedByUserId with their
     * password). Recorded on the sale. Leave null for an ordinary sale.
     */
    string? OverrideReason = null);

public sealed record VoidSaleRequest(string Reason);

public static class SalesEndpoints
{
    public static void MapSalesEndpoints(this IEndpointRouteBuilder app)
    {
        var group = app.MapGroup("/api/sales")
            .WithTags("Sales")
            .RequireAuthorization()
            .RequireRateLimiting("standard");

        group.MapPost("", CommitAsync)
             .RequireAuthorization(PermissionPolicy.For("pos.create_sale"));

        group.MapGet("/analytics", AnalyticsAsync)
             .RequireAuthorization(PermissionPolicy.For("dashboard.view"));

        group.MapGet("", ListAsync)
             .RequireAuthorization(PermissionPolicy.For("sales.view"));

        group.MapGet("/{saleId}", GetAsync)
             .RequireAuthorization(PermissionPolicy.For("sales.view_details"));

        group.MapPost("/{saleId}/void", VoidAsync)
             .RequireAuthorization(PermissionPolicy.For("sales.void"));
    }

    /// <summary>
    /// Commit a sale.
    ///
    /// The whole thing is one stored procedure call because the six writes it
    /// performs must succeed or fail together. Doing it here in six round trips
    /// would let a dropped connection halfway through leave stock reduced for a
    /// sale that does not exist.
    /// </summary>
    private static async Task<IResult> CommitAsync(
        CommitSaleRequest request,
        ISqlConnectionFactory db,
        ICurrentUser current,
        IPasswordHasher hasher,
        ILogger<Program> logger,
        CancellationToken ct)
    {
        if (request.Lines.Count == 0)
        {
            return Results.BadRequest(ApiError.Create(
                "empty_basket", "Add something to the sale first.", "أضف أصنافًا إلى الفاتورة أولًا."));
        }

        // A cashier must not post a sale to a branch they do not work at.
        if (!current.CanSeeBranch(request.BranchId))
        {
            return Results.Json(ApiError.Create(
                "branch_forbidden",
                "You cannot record a sale for that branch.",
                "لا يمكنك تسجيل فاتورة لهذا الفرع."), statusCode: 403);
        }

        /* The approver is someone this request can vouch for: the signed-in
           user, or another user whose password was just given. Whether they
           may approve — and whether approval is needed at all — is decided
           in the procedure, against their permissions as they stand. */
        var approverId = ProcErrors.Blank(request.ApprovedByUserId);

        if (approverId is not null && !string.Equals(approverId, current.UserId, StringComparison.Ordinal))
        {
            await using var check = db.Create();

            var approver = await check.QuerySingleOrDefaultAsync<(string? Hash, string? Salt)>(new CommandDefinition(
                "SELECT PasswordHash, PasswordSalt FROM core.AppUser WHERE UserId = @UserId AND Status = 'active';",
                new { UserId = approverId }, cancellationToken: ct));

            if (string.IsNullOrEmpty(request.ApproverPassword) ||
                approver.Hash is null || approver.Salt is null ||
                !hasher.Verify(request.ApproverPassword, approver.Hash, approver.Salt))
            {
                return Results.UnprocessableEntity(ApiError.Create(
                    "approval_invalid",
                    "The approver's password is not correct.",
                    "كلمة مرور المعتمِد غير صحيحة.",
                    new Dictionary<string, string[]> { ["approverPassword"] = ["The approver's password is not correct."] }));
            }
        }

        var lines = request.Lines.Select(line => new
        {
            line.ItemId, line.Quantity, line.UnitPriceH, line.LineDiscountH, line.Note
        });

        var payments = request.Payments.Select(payment => new
        {
            payment.Method, payment.AmountH, payment.Reference
        });

        await using var connection = db.Create();

        string saleId, invoiceNumber;

        try
        {
            (saleId, invoiceNumber) = await connection.QuerySingleAsync<(string, string)>(new CommandDefinition(
                """
                SELECT SaleId, InvoiceNumber FROM sales.usp_CommitSale(
                    p_BranchId => @BranchId, p_CustomerId => @CustomerId,
                    p_ServedByUserId => @ServedByUserId, p_CashierName => @CashierName,
                    p_DiscountId => @DiscountId, p_DiscountH => @DiscountH, p_TenderedH => @TenderedH,
                    p_IdempotencyKey => @IdempotencyKey, p_ApprovedByUserId => @ApprovedByUserId,
                    p_OrderType => @OrderType, p_CashierUserId => @CashierUserId,
                    p_OverrideReason => @OverrideReason,
                    p_Lines => @Lines::jsonb, p_Payments => @Payments::jsonb);
                """,
                new
                {
                    request.BranchId,
                    request.CustomerId,
                    request.ServedByUserId,
                    CashierName = current.Username,
                    request.DiscountId,
                    request.DiscountH,
                    request.TenderedH,
                    request.IdempotencyKey,
                    ApprovedByUserId = approverId,
                    OrderType = ProcErrors.Blank(request.OrderType)?.ToLowerInvariant(),
                    CashierUserId = current.UserId,
                    OverrideReason = ProcErrors.Blank(request.OverrideReason),
                    Lines = DbList.Json(lines),
                    Payments = DbList.Json(payments)
                },
                cancellationToken: ct));
        }
        catch (PostgresException ex) when (ex.ErrorNumber() is (>= 52000 and < 53000) or 63050 or 63051)
        {
            // The function's own rules. These are business outcomes, not
            // faults, so they come back as 422 with the reason intact.
            return Results.Json(
                Translate(ex.ErrorNumber(), ex.MessageText),
                statusCode: StatusCodes.Status422UnprocessableEntity);
        }

        logger.LogInformation("Sale {Invoice} committed at {Branch}.", invoiceNumber, request.BranchId);

        return Results.Created($"/api/sales/{saleId}", new { saleId, invoiceNumber });
    }

    /// <summary>
    /// The dashboard figures, aggregated in SQL.
    ///
    /// Fetching the period's sales and summing them in the browser would work
    /// at seed scale and fall over at a year of trading — and it would pull
    /// every line across the wire to produce eight numbers. The database is
    /// where the rows already are.
    ///
    /// The previous period is returned alongside, because a total without a
    /// comparison says nothing about whether things are going well.
    ///
    /// Returns count in the period they are issued, the way the ledger books
    /// them (4100 is debited on the credit note's date):
    /// <list type="bullet">
    /// <item><c>salesH</c> — invoices including VAT, less refunds on credit notes
    /// (<c>grossSalesH</c> − <c>returnsH</c>). Voided sales are excluded everywhere.</item>
    /// <item><c>netRevenueH</c> — the same excluding VAT: what the P&amp;L calls net revenue.</item>
    /// <item><c>cogsH</c>, <c>grossProfitH</c>, <c>grossMargin</c> — the gross-profit rule
    /// below, identical to GET /api/finance/summary.</item>
    /// </list>
    ///
    /// Gross profit, the one rule every screen uses:
    ///   net revenue   = sales excluding VAT − returns excluding VAT
    ///   cost of sales = line cost of the goods and services sold − line cost of what came back
    ///   gross profit  = net revenue − cost of sales
    ///   gross margin  = gross profit ÷ net revenue (never the VAT-inclusive price)
    /// </summary>
    private static async Task<IResult> AnalyticsAsync(
        ISqlConnectionFactory db, string? branchId, int days = 7,
        CancellationToken ct = default)
    {
        var window = days <= 0 ? 7 : Math.Min(days, 365);

        await using var connection = db.Create();

        /* The window ends now (whole seconds, as DATETIME2(0) kept it). */
        var now = DateTime.UtcNow;
        now = now.AddTicks(-(now.Ticks % TimeSpan.TicksPerSecond));

        await using var multi = await connection.QueryMultipleNamedAsync(new CommandDefinition(
            """
            /* Voided sales are excluded everywhere here: they are reversed in
               the ledger, and counting them would overstate every figure. */

            -- 1 and 2. This period and the one before it, for comparison.
            WITH Periods AS (
                SELECT 0 AS Prev, @Start AS FromUtc, @Now AS ToUtc
                UNION ALL
                SELECT 1, @PrevStart, @Start
            ),
            Sold AS (
                SELECT p.Prev,
                       COUNT(s.SaleId)::int                           AS Transactions,
                       COALESCE(SUM(s.TotalH), 0)::bigint             AS GrossSalesH,
                       COALESCE(SUM(s.TotalH - s.TaxH), 0)::bigint    AS NetSalesH,
                       COALESCE(SUM(c.CostH), 0)::bigint              AS CostH
                FROM Periods AS p
                LEFT JOIN sales.Sale AS s
                       ON s.Status <> 'voided'
                      AND s.SoldAtUtc >= p.FromUtc AND s.SoldAtUtc < p.ToUtc
                      AND (@BranchId IS NULL OR s.BranchId = @BranchId)
                LEFT JOIN LATERAL (
                    SELECT SUM(round(l.UnitCostH * l.Quantity, 0)::bigint) AS CostH
                    FROM sales.SaleLine AS l WHERE l.SaleId = s.SaleId
                ) AS c ON true
                GROUP BY p.Prev
            ),
            Returned AS (
                SELECT p.Prev,
                       COALESCE(SUM(r.RefundH), 0)::bigint    AS ReturnsH,
                       COALESCE(SUM(r.SubtotalH), 0)::bigint  AS NetReturnsH,
                       COALESCE(SUM(c.CostH), 0)::bigint      AS CostH
                FROM Periods AS p
                LEFT JOIN sales.SaleReturn AS r
                       ON r.ReturnedAtUtc >= p.FromUtc AND r.ReturnedAtUtc < p.ToUtc
                      AND (@BranchId IS NULL OR r.BranchId = @BranchId)
                LEFT JOIN LATERAL (
                    SELECT SUM(round(rl.UnitCostH * rl.Quantity, 0)::bigint) AS CostH
                    FROM sales.SaleReturnLine AS rl WHERE rl.ReturnId = r.ReturnId
                ) AS c ON true
                GROUP BY p.Prev
            )
            SELECT
                s.Prev,
                s.GrossSalesH - r.ReturnsH                         AS SalesH,
                s.GrossSalesH,
                r.ReturnsH,
                s.Transactions,
                CASE WHEN s.Transactions = 0 THEN 0
                     ELSE (s.GrossSalesH - r.ReturnsH) / s.Transactions END AS AverageH,
                s.NetSalesH - r.NetReturnsH                        AS NetRevenueH,
                s.CostH - r.CostH                                  AS CogsH,
                (s.NetSalesH - r.NetReturnsH) - (s.CostH - r.CostH) AS GrossProfitH
            FROM Sold AS s
            JOIN Returned AS r ON r.Prev = s.Prev
            ORDER BY s.Prev;

            -- 3. Daily totals, net of the refunds issued that day.
            SELECT Date, SUM(AmountH)::bigint AS SalesH
            FROM (
                SELECT s.SoldAtUtc::date AS Date, s.TotalH AS AmountH
                FROM sales.Sale AS s
                WHERE s.Status <> 'voided'
                  AND s.SoldAtUtc >= @Start
                  AND (@BranchId IS NULL OR s.BranchId = @BranchId)
                UNION ALL
                SELECT r.ReturnedAtUtc::date, -r.RefundH
                FROM sales.SaleReturn AS r
                WHERE r.ReturnedAtUtc >= @Start
                  AND (@BranchId IS NULL OR r.BranchId = @BranchId)
            ) AS d
            GROUP BY Date
            ORDER BY Date;

            -- 4. By payment method. Cash is stored as handed over (one row per
            --    sale), so the change given back is taken off to show takings,
            --    and refunds come off the method they were paid back by.
            SELECT Method, SUM(AmountH)::bigint AS AmountH
            FROM (
                SELECT p.Method,
                       p.AmountH - CASE WHEN p.Method = 'cash' THEN s.ChangeH ELSE 0 END AS AmountH
                FROM sales.SalePayment AS p
                JOIN sales.Sale AS s ON s.SaleId = p.SaleId
                WHERE s.Status <> 'voided'
                  AND s.SoldAtUtc >= @Start
                  AND (@BranchId IS NULL OR s.BranchId = @BranchId)
                UNION ALL
                SELECT COALESCE(r.RefundMethod, 'cash'), -r.RefundH
                FROM sales.SaleReturn AS r
                WHERE r.ReturnedAtUtc >= @Start
                  AND (@BranchId IS NULL OR r.BranchId = @BranchId)
            ) AS m
            GROUP BY Method;

            -- 5. Best sellers, by what was sold and kept: returned quantities
            --    (and their share of the line discount) are taken off.
            SELECT
                l.ItemId, l.NameAr, l.NameEn,
                SUM(l.Quantity - l.ReturnedQty)          AS Quantity,
                SUM(round((l.UnitPriceH * l.Quantity - l.LineDiscountH)
                          * (l.Quantity - l.ReturnedQty) / NULLIF(l.Quantity, 0), 0)::bigint)::bigint AS RevenueH
            FROM sales.SaleLine AS l
            JOIN sales.Sale AS s ON s.SaleId = l.SaleId
            WHERE s.Status <> 'voided'
              AND s.SoldAtUtc >= @Start
              AND (@BranchId IS NULL OR s.BranchId = @BranchId)
              AND l.Quantity - l.ReturnedQty > 0
            GROUP BY l.ItemId, l.NameAr, l.NameEn
            ORDER BY RevenueH DESC
            LIMIT 5;
            """,
            new
            {
                Now = now,
                Start = now.AddDays(-window),
                PrevStart = now.AddDays(-(window * 2)),
                BranchId = branchId
            },
            cancellationToken: ct));

        var periods = (await multi.ReadAsync<AnalyticsPeriod>()).ToList();
        var daily = (await multi.ReadRowsAsync()).ToList();
        var byMethod = (await multi.ReadRowsAsync()).ToList();
        var topItems = (await multi.ReadRowsAsync()).ToList();

        object Shape(AnalyticsPeriod p) => new
        {
            salesH = p.SalesH,
            grossSalesH = p.GrossSalesH,
            returnsH = p.ReturnsH,
            transactions = p.Transactions,
            averageH = p.AverageH,
            netRevenueH = p.NetRevenueH,
            cogsH = p.CogsH,
            grossProfitH = p.GrossProfitH,
            grossMargin = p.NetRevenueH > 0 ? Math.Round((decimal)p.GrossProfitH / p.NetRevenueH, 4) : (decimal?)null
        };

        var current = Shape(periods.Single(p => p.Prev == 0));
        var previous = Shape(periods.Single(p => p.Prev == 1));

        return Results.Ok(new { current, previous, daily, byMethod, topItems });
    }

    private sealed record AnalyticsPeriod
    {
        public int Prev { get; init; }
        public long SalesH { get; init; }
        public long GrossSalesH { get; init; }
        public long ReturnsH { get; init; }
        public int Transactions { get; init; }
        public long AverageH { get; init; }
        public long NetRevenueH { get; init; }
        public long CogsH { get; init; }
        public long GrossProfitH { get; init; }
    }

    /// <summary>
    /// A page of sale headers, newest first.
    ///
    /// Status and payment method are filtered here, in SQL, so the count, the
    /// pages and the summary all describe the filtered set. Narrowing the
    /// loaded page in the browser showed 3 of 9 voided sales — the ones that
    /// happened to fall on page one.
    /// </summary>
    /// <remarks>
    /// <c>status</c>: completed | voided | partially_returned | returned.
    /// <c>method</c>: cash | card | credit | bank — a sale that used that
    /// method at all, alone or with another — or <c>mixed</c> for sales paid
    /// more than one way. Each row carries <c>paymentMethod</c> (the one method,
    /// or <c>mixed</c>) and <c>itemCount</c>. <c>summary</c> totals the whole
    /// filtered set: <c>netH</c> (sales that are not voided, less the refunds
    /// on their credit notes), <c>returnsH</c> (those refunds), <c>invoices</c>
    /// (not voided) and <c>returned</c> (returned or partially returned).
    /// </remarks>
    private static async Task<IResult> ListAsync(
        ISqlConnectionFactory db,
        ICurrentUser current,
        string? branchId,
        string? search,
        DateOnly? from,
        DateOnly? to,
        string? status,
        string? method,
        int page = 1,
        int pageSize = 25,
        CancellationToken ct = default)
    {
        var paging = new PageQuery { Page = page <= 0 ? 1 : page, PageSize = pageSize };

        var statusFilter = ProcErrors.Blank(status)?.ToLowerInvariant();
        var methodFilter = ProcErrors.Blank(method)?.ToLowerInvariant();

        if (statusFilter is not null and not ("completed" or "voided" or "partially_returned" or "returned"))
        {
            return Results.UnprocessableEntity(ApiError.Create(
                "bad_status",
                "Status is completed, voided, partially_returned or returned.",
                "الحالة: مكتملة أو ملغاة أو مرتجعة جزئيًا أو مرتجعة.",
                new Dictionary<string, string[]> { ["status"] = ["Unknown status."] }));
        }

        if (methodFilter is not null and not ("cash" or "card" or "credit" or "bank" or "mixed"))
        {
            return Results.UnprocessableEntity(ApiError.Create(
                "bad_method",
                "Payment method is cash, card, credit, bank or mixed.",
                "طريقة الدفع: نقدًا أو بطاقة أو آجل أو تحويل أو مختلطة.",
                new Dictionary<string, string[]> { ["method"] = ["Unknown payment method."] }));
        }

        await using var connection = db.Create();

        const string filter = """
            WHERE (@BranchId IS NULL OR s.BranchId = @BranchId OR s.BranchId IS NULL)
              AND (@Search IS NULL OR s.InvoiceNumber COLLATE "default" ILIKE '%' || @Search || '%')
              AND (@From IS NULL OR s.SoldAtUtc::date >= @From)
              AND (@To   IS NULL OR s.SoldAtUtc::date <= @To)
              AND (@Status IS NULL OR s.Status = @Status)
              AND (@Method IS NULL
                   OR (@Method = 'mixed' AND s.PaymentMethod = 'mixed')
                   OR (@Method <> 'mixed' AND EXISTS (
                           SELECT 1 FROM sales.SalePayment AS p
                           WHERE p.SaleId = s.SaleId AND p.Method = @Method AND p.AmountH > 0)))
            """;

        var sql = $"""
            /* Net of returns: what these sales took less what their credit
               notes refunded (SaleReturn.RefundH, VAT inclusive — the figure
               the finance summary's returnsH sums), so the KPI agrees with it. */
            SELECT COUNT(*)::int AS TotalCount,
                   (COALESCE(SUM(CASE WHEN s.Status <> 'voided' THEN s.TotalH END), 0)
                     - COALESCE(SUM(CASE WHEN s.Status <> 'voided' THEN rf.RefundH END), 0))::bigint AS NetH,
                   SUM(CASE WHEN s.Status <> 'voided' THEN 1 ELSE 0 END)::int AS Invoices,
                   SUM(CASE WHEN s.Status IN ('returned', 'partially_returned') THEN 1 ELSE 0 END)::int AS Returned,
                   COALESCE(SUM(CASE WHEN s.Status <> 'voided' THEN rf.RefundH END), 0)::bigint AS ReturnsH
            FROM sales.vw_SaleSummary AS s
            LEFT JOIN LATERAL (SELECT SUM(r.RefundH) AS RefundH
                               FROM sales.SaleReturn AS r WHERE r.SaleId = s.SaleId) AS rf ON true
            {filter};

            SELECT *
            FROM sales.vw_SaleSummary AS s
            {filter}
            ORDER BY s.SoldAtUtc DESC
            OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
            """;

        await using var multi = await connection.QueryMultipleNamedAsync(new CommandDefinition(sql,
            new
            {
                BranchId = branchId,
                Search = string.IsNullOrWhiteSpace(search) ? null : search.Trim(),
                From = from,
                To = to,
                Status = statusFilter,
                Method = methodFilter,
                paging.Offset,
                paging.PageSize
            },
            cancellationToken: ct));

        var totals = await multi.ReadSingleAsync<(int TotalCount, long NetH, int? Invoices, int? Returned, long ReturnsH)>();
        var rows = (await multi.ReadRowsAsync()).ToList();

        var result = new PagedResult<object>
        {
            Items = rows.Cast<object>().ToList(),
            Page = paging.Page,
            PageSize = paging.PageSize,
            TotalCount = totals.TotalCount
        };

        return Results.Ok(new
        {
            result.Items,
            result.Page,
            result.PageSize,
            result.TotalCount,
            result.TotalPages,
            Summary = new
            {
                totals.NetH,
                totals.ReturnsH,
                Invoices = totals.Invoices ?? 0,
                Returned = totals.Returned ?? 0
            }
        });
    }

    private static async Task<IResult> GetAsync(
        string saleId,
        ISqlConnectionFactory db,
        CancellationToken ct)
    {
        await using var connection = db.Create();

        await using var multi = await connection.QueryMultipleNamedAsync(new CommandDefinition(
            """
            SELECT * FROM sales.vw_SaleSummary WHERE SaleId = @SaleId;
            SELECT * FROM sales.SaleLine    WHERE SaleId = @SaleId ORDER BY SaleLineId;
            SELECT * FROM sales.SalePayment WHERE SaleId = @SaleId;
            """,
            new { SaleId = saleId },
            cancellationToken: ct));

        var sale = await multi.ReadSingleRowOrDefaultAsync();
        if (sale is null) return Results.NotFound();

        var lines = (await multi.ReadRowsAsync()).ToList();
        var payments = (await multi.ReadRowsAsync()).ToList();

        return Results.Ok(new { sale, lines, payments });
    }

    private static async Task<IResult> VoidAsync(
        string saleId,
        VoidSaleRequest request,
        ISqlConnectionFactory db,
        ICurrentUser current,
        CancellationToken ct)
    {
        await using var connection = db.Create();

        try
        {
            await connection.ExecuteAsync(new CommandDefinition(
                "SELECT sales.usp_VoidSale(p_SaleId => @SaleId, p_Reason => @Reason, p_Actor => @Actor);",
                new { SaleId = saleId, request.Reason, Actor = current.Username },
                cancellationToken: ct));
        }
        catch (PostgresException ex) when (ex.ErrorNumber() == 67012)
        {
            return ProcErrors.Conflict("sale_has_returns",
                "This sale has returns against it and cannot be voided. Return the remaining items instead.",
                "على هذه الفاتورة مرتجعات ولا يمكن إلغاؤها. أرجع الأصناف المتبقية بدلًا من ذلك.");
        }
        catch (PostgresException ex) when (ex.ErrorNumber() >= 52000 && ex.ErrorNumber() < 53000)
        {
            return Results.Json(Translate(ex.ErrorNumber(), ex.MessageText),
                statusCode: StatusCodes.Status422UnprocessableEntity);
        }

        return Results.NoContent();
    }

    /// <summary>
    /// Turn a procedure's error number into a bilingual message.
    ///
    /// The database speaks English only, and an Arabic cashier should not meet
    /// an English error at the till.
    /// </summary>
    internal static ApiError Translate(int number, string fallback) => number switch
    {
        52000 => ApiError.Create("empty_basket",
            "A sale needs at least one line.", "الفاتورة تحتاج صنفًا واحدًا على الأقل."),
        52001 => ApiError.Create("bad_quantity",
            "Quantities must be above zero.", "يجب أن تكون الكميات أكبر من صفر."),
        52002 => ApiError.Create("unknown_item",
            "One of the items is no longer available.", "أحد الأصناف لم يعد متاحًا."),
        52003 => ApiError.Create("insufficient_stock",
            "There is not enough stock for one or more items.", "الكمية غير كافية لصنف أو أكثر."),
        52004 => ApiError.Create("discount_too_large",
            "The discount is more than the basket total.", "الخصم أكبر من إجمالي الفاتورة."),
        52005 => ApiError.Create("underpaid",
            "The payments do not cover the total.", "المدفوعات لا تغطي الإجمالي."),
        52006 => ApiError.Create("credit_needs_customer",
            "A credit sale needs a customer.", "البيع الآجل يحتاج إلى عميل."),
        52007 => ApiError.Create("over_credit_limit",
            "This would take the customer over their credit limit.",
            "هذا سيتجاوز حدّ الائتمان للعميل."),
        52010 => ApiError.Create("sale_not_found", "Sale not found.", "الفاتورة غير موجودة."),
        52011 => ApiError.Create("already_voided",
            "This sale is already voided.", "هذه الفاتورة ملغاة مسبقًا."),
        52012 => ApiError.Create("reason_required",
            "A void needs a reason.", "الإلغاء يحتاج إلى سبب."),
        52020 => ApiError.Create("bad_amount",
